import { validateChatState } from './chat-state.6be1c4db8d30.js';

const MAX_TEXT = 500;
function text(value, field) { const result = String(value ?? '').trim(); if (!result) throw new TypeError(`${field} 不可空白`); if (result.length > MAX_TEXT) throw new TypeError(`${field} 最多 ${MAX_TEXT} 字`); return result; }
function copy(value) { return typeof structuredClone === 'function' ? structuredClone(value) : JSON.parse(JSON.stringify(value)); }
function base(state, timestamp) { return validateChatState(state, timestamp); }
function update(state, entries, timestamp) { return { ...state, updatedAt: timestamp, worldRules: { schemaVersion: 1, entries } }; }
export function suggestWorldRule(state, input, timestamp = new Date().toISOString()) { const current = base(state, timestamp); const ruleKey = text(input?.ruleKey, '規則鍵'); const existing = current.worldRules.entries.find((x) => x.ruleKey === ruleKey); if (existing) return current; const entry = { schemaVersion: 1, ruleKey, type: text(input?.type ?? 'general', '規則類型'), description: text(input?.description, '規則說明'), evidence: input?.evidence ? copy(input.evidence) : null, status: 'suggested', createdAt: timestamp, updatedAt: timestamp }; return update(current, [...current.worldRules.entries, entry], timestamp); }
function change(state, ruleKey, status, timestamp) { const current = base(state, timestamp); const found = current.worldRules.entries.some((x) => x.ruleKey === ruleKey); if (!found) throw new RangeError('找不到世界規則'); return update(current, current.worldRules.entries.map((x) => x.ruleKey === ruleKey ? { ...x, status, updatedAt: timestamp } : x), timestamp); }
export function confirmWorldRule(state, ruleKey, timestamp) { return change(state, text(ruleKey, '規則鍵'), 'confirmed', timestamp); }
export function rejectWorldRule(state, ruleKey, timestamp) { return change(state, text(ruleKey, '規則鍵'), 'rejected', timestamp); }
export function editWorldRule(state, ruleKey, description, timestamp = new Date().toISOString()) { const current = base(state, timestamp); const key = text(ruleKey, '規則鍵'); const next = text(description, '規則說明'); const rule = current.worldRules.entries.find((x) => x.ruleKey === key); if (!rule) throw new RangeError('找不到世界規則'); if (rule.status !== 'confirmed') throw new TypeError('只可編輯已確認規則'); return update(current, current.worldRules.entries.map((x) => x.ruleKey === key ? { ...x, description: next, updatedAt: timestamp } : x), timestamp); }
export function deleteWorldRule(state, ruleKey, timestamp = new Date().toISOString()) { const current = base(state, timestamp); const key = text(ruleKey, '規則鍵'); const rule = current.worldRules.entries.find((x) => x.ruleKey === key); if (!rule) throw new RangeError('找不到世界規則'); if (rule.status !== 'confirmed') throw new TypeError('只可刪除已確認規則'); return update(current, current.worldRules.entries.filter((x) => x.ruleKey !== key), timestamp); }
